#undef HWY_TARGET_INCLUDE
#define HWY_TARGET_INCLUDE "stdlib/blas/base/daxpy_kernel_inl.h"

// note that the order of includes matters here...

#include <hwy/foreach_target.h> // includes HWY_TARGET_INCLUDE once for each target
#include <hwy/highway.h>
#include "stdlib/blas/base/shared.h"

// foreach_target.h compiles the kernel for all NON-static targets.
// Now compile it for the static target that was skipped.
#include HWY_TARGET_INCLUDE

// do this once for each target
#if HWY_ONCE

// export the kernels for dynamic dispatch
HWY_EXPORT( daxpy_kernel_simd );
HWY_EXPORT( daxpy_strided_kernel );

// declare with C linkage without any namespaces
extern "C" void daxpy_simd( CBLAS_INT N, double alpha, const double *X, const CBLAS_INT strideX, const CBLAS_INT offsetX, double *Y, const CBLAS_INT strideY, const CBLAS_INT offsetY ) {
	if ( N <= 0 ) {
		return;
	}

	if ( strideX == 1 && strideY == 1 ) {
		// if contiguous memory then use optimised simd kernel
		HWY_DYNAMIC_DISPATCH( daxpy_kernel_simd )( N, alpha, X, offsetX, Y, offsetY );
	} else {
		// TODO: see scatter and gather instructions and determine if this can be optimised else call daxpy_ndarray
		HWY_DYNAMIC_DISPATCH( daxpy_strided_kernel )( N, alpha, X, strideX, offsetX, Y, strideY, offsetY );
	}
}

#endif
